const cheerio = require('cheerio');

const defaultCount = 60;

function extract(input, cheerio) {
  const $ = cheerio.load(input);

  // Read the <title> text
  const title = $('title').text().trim();

  // Extract the first number in the title
  const match = title.match(/\d+/);
  const count = match ? parseInt(match[0], 10) : defaultCount;

  return {
    offerCount: count
  };
}

const offerCount = extract($input.first().json.data, cheerio);

return [{ json: offerCount }];

const initialURL = $('Loop Over URLs').last().json.url;
const scrollStep = 10;
const offerCount = Math.min($input.first().json.offerCount, 150);

const defaultScrollURL = initialURL.replace(
  "https://www.linkedin.com/jobs/search/?",
  "https://www.linkedin.com/jobs-guest/jobs/api/seeMoreJobPostings/search?"
) + "&start=";

const urls = [initialURL]
for (let i = 60; i < offerCount; i += scrollStep) {
  urls.push(defaultScrollURL + i);
}

return urls.map(url => ({ json: { url, jobs: [] }}))

const cheerio = require('cheerio');

function parseRelativeDate(text) {
    const now = new Date();
    const lower = text.toLowerCase();

    const m = lower.match(/(\d+)\s*(minute|hour|day)s?\s*ago/);
    if (!m) return null;

    const value = parseInt(m[1], 10);
    const unit = m[2];

    const d = new Date(now);

    if (unit === "minute") d.setMinutes(now.getMinutes() - value);
    if (unit === "hour")   d.setHours(now.getHours() - value);
    if (unit === "day")    d.setDate(now.getDate() - value);

    return d.toISOString();
}

function todayDate() {
    const d = new Date();
    d.setHours(0, 0, 0, 0);
    return d.toISOString();
}

function isMasked(text) {
    if (!text) return true;
    return !/\p{L}{2,}/u.test(text);
}

function titleFromLink(link) {
    try {
        const slug = link
            .split('/jobs/view/')[1]
            .replace(/\?.*$/, '')
            .replace(/-\d+$/, '');

        return decodeURIComponent(slug)
            .replace(/-/g, ' ')
            .replace(/\bat\b.*$/i, '')
            .trim();
    } catch {
        return null;
    }
}

function companyFromLink(link) {
    try {
        const slug = link
            .split('/jobs/view/')[1]
            .replace(/\?.*$/, '')
            .replace(/-\d+$/, '');

        const atIndex = slug.lastIndexOf('-at-');
        if (atIndex === -1) return null;

        const companySlug = slug.slice(atIndex + 4);

        return decodeURIComponent(companySlug)
            .replace(/-/g, ' ')
            .trim();
    } catch {
        return null;
    }
}

const html = $input.first().json.data;
const $$ = cheerio.load(html);

const jobs = [];

$$('.base-search-card').each((i, el) => {
    const card = $$(el);

    /* ---------------------------
       LINK (robust to both layouts)
    ---------------------------- */

    let link =
        card.find('a.base-card__full-link').attr('href') || // normal layout
        card.attr('href') ||                                 // wrapped layout
        null;

    /* ---------------------------
       JOB ID (robust & preferred)
    ---------------------------- */

    let jobId = null;

    // Preferred: data-entity-urn
    const urn = card.attr('data-entity-urn');
    if (urn) {
        const match = urn.match(/jobPosting:(\d+)/);
        jobId = match ? match[1] : null;
    }

    // Fallback: extract from link if urn missing
    if (!jobId && link) {
        const match = link.match(/-(\d+)(?:\?|$)/);
        jobId = match ? match[1] : null;
    }

    /* ---------------------------
       JOB TITLE
    ---------------------------- */

    let jobTitle =
        card.find('.base-search-card__title').text().trim() ||
        card.find('span.sr-only').text().trim() ||
        null;

    if (isMasked(jobTitle) && link) {
        jobTitle = titleFromLink(link);
    }

    /* ---------------------------
       COMPANY
    ---------------------------- */

    let companyName =
        card.find('.base-search-card__subtitle a').text().trim() ||
        card.find('.base-search-card__subtitle').text().trim() ||
        null;

    if (isMasked(companyName) && link) {
        companyName = companyFromLink(link);
    }

    /* ---------------------------
       POSTED DATE
    ---------------------------- */

    const postedText = card.find('time').text().trim();
    let postedAt = parseRelativeDate(postedText);

    if (!postedAt) postedAt = todayDate();

    /* ---------------------------
       PUSH RESULT
    ---------------------------- */

    jobs.push({
        jobId,
        jobTitle,
        companyName,
        link,
        postedAt
    });
});

const url = $('Loop Over Scrolls').last().json.url;

return [{ json: { url, jobs } }];

