}));

const cheerio = require('cheerio');

const html = $input.first().json.data
const $$ = cheerio.load(html);

// 1. Extract the JSON-LD script (LinkedIn job pages always include this)
let description = "";

$$('script[type="application/ld+json"]').each((_, el) => {
    try {
        const json = JSON.parse($$(el).contents().text());

        // When the script contains a JobPosting
        if (json['@type'] === 'JobPosting' && json.description) {
            description = json.description;
        }
    } catch (e) {
        // ignore parsing errors from other scripts
    }
});

// Fallback to HTML description if JSON-LD missing
if (!description) {
    description = $$('.description__text.description__text--rich').html();
}

// 2. Clean HTML entities + line breaks
if (description) {
    // Remove HTML tags but keep line breaks
    description = description
        .replace(/<br\s*\/?>/gi, "\n")
        .replace(/<\/?[^>]+>/g, "")
        .trim();
}

// 3. Return in n8n format
return [
    {
        json: {
            jobDescription: description || '',
        }
    }
];

const TurndownService = require('turndown');
const turndown = new TurndownService();
const escapedHtml = $input.first().json.jobDescription;

// Decode HTML entities using native browser-like API
function decodeHtmlEntities(text) {
  // Manual decoding for common entities
  return text
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&apos;/g, "'")
    .replace(/&nbsp;/g, ' ')
    // Numeric entities
    .replace(/&#(\d+);/g, (match, dec) => String.fromCharCode(dec))
    .replace(/&#x([0-9a-f]+);/gi, (match, hex) => String.fromCharCode(parseInt(hex, 16)));
}

// 1. Decode HTML entities
const realHtml = decodeHtmlEntities(escapedHtml);

// 2. Convert to Markdown
const markdown = turndown.turndown(realHtml);

return [{ json: { jobDescription: markdown } }];

