let jobs = $input.all().map(item => item.json);

let emailBody = 'Hello,\n\nHere are the new job opportunities today:\n\n';

jobs.forEach((job, index) => {
  emailBody += `${index+1}) ${job.title} — ${job.company} — ${job.location}\n`;
  emailBody += `    Skills: ${job['profileSkills'].join(', ')}\n`;
  emailBody += `    Apply here: ${job['url']}\n\n`;
});

emailBody += `Total new positions: ${jobs.length}\n`;

return [{ json: { body: emailBody, nb_positions: jobs.length } }];

